<template>
  <div v-loading="loading" class="workload-editor">
    <div class="editor-title"><div><router-link :to="listPath">← 工作负载列表</router-link><h1>{{ editing ? '编辑工作负载' : '创建工作负载' }}</h1><p class="muted">{{ namespace }} · 表单与 YAML 共用完整配置，未展示的字段仍保留</p></div><el-radio-group :model-value="mode" @change="switchMode"><el-radio-button value="form">表单配置</el-radio-button><el-radio-button value="yaml">YAML {{ editing ? '编辑' : '创建' }}</el-radio-button></el-radio-group></div>
    <el-steps v-if="mode === 'form'" :active="step" simple class="editor-steps"><el-step v-for="(label,index) in steps" :key="label" :title="label" @click="goStep(index)" /></el-steps>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <div v-if="errors.length" role="alert" class="validation-errors"><strong>请修正 {{ errors.length }} 项问题</strong><p v-for="item in errors" :key="item.path+item.message">{{ item.path }}：{{ item.message }}</p></div>
    <div v-if="!loadFailed" class="editor-layout"><div class="editor-content">
      <section v-if="mode === 'yaml'" class="ks-card"><div class="editor-toolbar"><label>导入清单 <input type="file" accept=".yml,.yaml" @change="importFile" /></label><el-button @click="validateYaml">校验</el-button><el-button @click="simplifyYaml">{{editing?'复制精简 YAML':'精简 YAML'}}</el-button><el-button @click="copyYaml(yamlText)">复制 YAML</el-button></div><el-input v-model="yamlText" class="yaml-input" type="textarea" :rows="28" spellcheck="false" /><p class="muted">支持完整或精简的单资源 YAML。精简仅清除状态与服务端生成字段，不删除用户配置。</p></section>
      <template v-else>
        <section v-if="step===0" class="ks-card"><h2>基本信息</h2><div class="editor-toolbar"><label>类型 <el-select :model-value="object.kind" :disabled="editing" @change="changeKind"><el-option v-for="kind in ['Deployment','StatefulSet','DaemonSet']" :key="kind" :label="kind" :value="kind" /></el-select></label><span>命名空间：{{ namespace }}</span></div><SchemaFields v-model="object.metadata" :fields="basicFields.map(field=>field.key==='name'?{...field,disabled:editing}:field)" /><h2 class="section-gap">Pod 标签</h2><SchemaFields v-model="object.spec.template.metadata" :fields="[{key:'labels',label:'Pod 模板标签',type:'map'},{key:'annotations',label:'Pod 注解',type:'map'}]" /><h2 class="section-gap">工作负载选择器</h2><SchemaFields v-model="object.spec.selector" :fields="[{key:'matchLabels',label:'匹配标签',type:'map'}]" /><p class="muted">Pod 标签必须满足选择器；编辑已有对象时不要修改其不可变选择器。</p></section>
        <template v-if="step===1">
          <section class="ks-card"><h2>副本与更新策略</h2><SchemaFields v-model="object.spec" :fields="strategyFields" /></section>
          <section class="ks-card"><div class="editor-toolbar"><h2>容器配置</h2><el-button @click="addContainer('containers')">添加应用容器</el-button><el-button @click="addContainer('initContainers')">添加 Init 容器</el-button></div><div class="container-choices"><el-button v-for="(c,i) in pod.containers" :key="'app'+i" :type="group==='containers'&&selected===i?'primary':''" @click="selectContainer('containers',i)">{{ c.name || '未命名' }} · 应用</el-button><el-button v-for="(c,i) in pod.initContainers||[]" :key="'init'+i" :type="group==='initContainers'&&selected===i?'primary':''" @click="selectContainer('initContainers',i)">{{ c.name || '未命名' }} · Init</el-button></div><el-tabs v-model="containerTab" :before-leave="guardDrafts"><el-tab-pane v-for="(_,tab) in containerFields" :key="tab" :label="tab" :name="tab" /></el-tabs><template v-if="currentContainer"><el-alert v-if="group==='initContainers'&&containerTab==='健康检查'" type="info" title="普通初始化容器不使用健康探针" :closable="false" /><SchemaFields v-else :key="group+selected+containerTab" :model-value="currentContainer" :fields="containerFields[containerTab]" @update:model-value="updateContainer" /><div class="section-gap"><el-button type="danger" plain @click="removeContainer">删除此容器</el-button></div></template></section>
        </template>
        <template v-if="step===2">
          <section class="ks-card"><h2>存储卷</h2><p class="muted">每个卷只启用一种来源。先定义卷，再按容器设置挂载。</p><SchemaFields v-model="object.spec.template.spec" :fields="[{key:'volumes',label:'卷列表',type:'array',fields:volumeFields,initial:{name:'data',emptyDir:{}}}]" /></section>
          <section v-if="object.kind==='StatefulSet'" class="ks-card"><h2>独立 PVC 模板</h2><SchemaFields v-model="object.spec" :fields="[{key:'volumeClaimTemplates',label:'卷声明模板',type:'array',fields:claimFields,initial:{metadata:{name:'data'},spec:{storageClassName:'local-path',accessModes:['ReadWriteOnce'],resources:{requests:{storage:'10Gi'}}}}}]" /></section>
          <section v-for="(c,index) in pod.containers" :key="c.name+index" class="ks-card"><h2>{{ c.name }} · 容器挂载</h2><p class="muted">可引用卷：{{ volumeNames.join('、') || '请先创建卷' }}</p><SchemaFields :model-value="c" :fields="[{key:'volumeMounts',label:'挂载',type:'array',fields:mountFields,initial:{name:volumeNames[0]||'',mountPath:'/data'}}]" @update:model-value="pod.containers[index]=$event" /></section>
          <section v-for="(c,index) in pod.initContainers||[]" :key="'init'+index" class="ks-card"><h2>{{ c.name }} · Init 容器挂载</h2><SchemaFields :model-value="c" :fields="[{key:'volumeMounts',label:'挂载',type:'array',fields:mountFields}]" @update:model-value="pod.initContainers[index]=$event" /></section>
        </template>
        <section v-if="step===3" class="ks-card"><h2>调度、身份与安全</h2><SchemaFields v-model="object.spec.template.spec" :fields="advancedFields" /><p class="muted">Pod 亲和性、拓扑分布等其他字段可在 YAML 中设置，切回表单后仍保留。</p></section>
        <section v-if="step===4" class="ks-card"><h2>{{ editing?'提交变更前确认':'创建前确认' }}</h2><div class="review-summary"><div><span>对象</span><strong>{{ object.kind }} / {{ object.metadata.name }}</strong></div><div><span>范围</span><strong>{{ namespace }}</strong></div><div><span>容器</span><strong>{{ pod.containers.length }} 个应用 / {{ pod.initContainers?.length||0 }} 个 Init</strong></div><div><span>运行方式</span><strong>{{ object.kind==='DaemonSet'?'按匹配节点运行':object.spec.replicas+' 副本' }}</strong></div></div><div class="editor-toolbar"><el-button @click="copyYaml(preview)">复制{{ editing?'当前':'精简' }} YAML</el-button><el-button @click="switchMode('yaml')">继续编辑 YAML</el-button></div><pre class="editor-preview">{{ preview }}</pre><p class="muted">最终提交还受集群 RBAC、准入和配额约束。</p></section>
      </template>
    </div><aside class="ks-card editor-summary"><h3>配置摘要</h3><dl><dt>对象</dt><dd>{{ object.metadata.name || '未填写' }}</dd><dt>类型</dt><dd>{{ object.kind }}</dd><dt>容器</dt><dd>{{ pod.containers.length }} 个应用容器</dd><dt>存储</dt><dd>{{ volumeNames.length }} 个卷来源</dd><dt>草稿</dt><dd>切换步骤保留配置</dd></dl></aside></div>
    <div class="editor-footer"><router-link :to="listPath">取消并返回列表</router-link><div><el-button v-if="mode==='form'&&step>0" @click="goStep(step-1)">上一步</el-button><el-button :disabled="loadFailed" v-if="mode==='form'&&step<4" type="primary" @click="goStep(step+1)">下一步</el-button><el-button :disabled="loadFailed" v-else-if="mode==='yaml'" type="primary" @click="reviewYaml">解析并确认</el-button><el-button :disabled="loadFailed" v-else type="primary" :loading="saving" @click="submit">{{ editing?'保存配置':'确认创建' }}</el-button></div></div>
  </div>
</template>
<script setup>
import { computed,onMounted,provide,reactive,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import { loadAll,dump } from 'js-yaml'
import http from '../api/http'
import {copyText} from '../utils/clipboard'
import SchemaFields from '../components/SchemaFields.vue'
import { initial,setKind,simplify,validate } from '../utils/workloadModel'
import { containerFields,basicFields,volumeFields,mountFields,advancedFields,claimFields } from '../utils/workloadFields'
const route=useRoute(),router=useRouter(),namespace=String(route.params.namespace||'default'),editing=!!route.params.name
const object=ref(setKind(initial(namespace),{deployment:'Deployment',statefulset:'StatefulSet',daemonset:'DaemonSet'}[route.query.kind]||'Deployment')),step=ref(0),mode=ref(route.query.mode==='yaml'?'yaml':'form'),loading=ref(false),saving=ref(false),error=ref(''),errors=ref([]),yamlText=ref(''),group=ref('containers'),selected=ref(0),containerTab=ref('镜像与资源')
const fieldErrors=reactive({}),loadFailed=ref(false)
provide('workloadFieldErrors',fieldErrors)
const steps=['基本信息','Pod 设置','存储挂载','高级设置','确认创建']
const listPath='/projects/'+encodeURIComponent(namespace)+'/workloads?kind='+String(route.params.kind||route.query.kind||'deployment')
const pod=computed(()=>object.value.spec.template.spec),currentContainer=computed(()=>pod.value[group.value]?.[selected.value])
const volumeNames=computed(()=>[...(pod.value.volumes||[]).map(v=>v.name),...(object.value.spec.volumeClaimTemplates||[]).map(v=>v.metadata.name)])
const preview=computed(()=>dump(editing?object.value:simplify(object.value),{lineWidth:-1,noRefs:true}))
const strategyFields=computed(()=>{
 const kind=object.value.kind,fields=[]
 if(kind!=='DaemonSet')fields.push({key:'replicas',label:'期望副本数',type:'number',min:0})
 if(kind==='StatefulSet')fields.push({key:'serviceName',label:'Headless Service 名称',required:true,help:'引用已存在的服务，不自动创建'},{key:'podManagementPolicy',label:'Pod 管理策略',type:'select',options:['OrderedReady','Parallel']})
 const key=kind==='Deployment'?'strategy':'updateStrategy',type=object.value.spec[key]?.type
 fields.push({key,label:'更新策略',type:'object',fields:[{key:'type',label:'策略',type:'select',options:kind==='Deployment'?['RollingUpdate','Recreate']:['RollingUpdate','OnDelete']},...(type==='RollingUpdate'?[{key:'rollingUpdate',label:'滚动配置',type:'object',fields:kind==='StatefulSet'?[{key:'partition',label:'分区 partition',type:'number'}]:[{key:'maxUnavailable',label:'最大不可用（整数或百分比）',type:'port'},...(kind==='Deployment'?[{key:'maxSurge',label:'最大额外副本（整数或百分比）',type:'port'}]:[])]}]:[])]})
 return fields
})
function guardDrafts(){if(Object.keys(fieldErrors).length){error.value=Object.values(fieldErrors).join('；');return false}return true}
function goStep(value){if(guardDrafts())step.value=value}
function selectContainer(type,index){if(guardDrafts()){group.value=type;selected.value=index}}
function updateContainer(value){pod.value[group.value][selected.value]=value}
function addContainer(type){if(!guardDrafts())return;pod.value[type]||=[];pod.value[type].push({name:(type==='containers'?'app':'init')+'-'+(pod.value[type].length+1),image:type==='containers'?'nginx:1.27.5':'busybox:1.37.0',imagePullPolicy:'IfNotPresent'});group.value=type;selected.value=pod.value[type].length-1;containerTab.value='镜像与资源'}
function removeContainer(){if(!guardDrafts())return;if(group.value==='containers'&&pod.value.containers.length===1)return ElMessage.warning('至少保留一个应用容器');pod.value[group.value].splice(selected.value,1);group.value='containers';selected.value=0}
async function changeKind(kind){try{await ElMessageBox.confirm('切换类型将移除不兼容的副本、更新策略和卷模板字段。','切换工作负载类型')}catch{return}object.value=setKind(object.value,kind)}
function parseYaml(){try{const docs=loadAll(yamlText.value).filter(Boolean);if(docs.length!==1)throw Error('请提供一个资源文档，多资源请分别创建');const parsed=docs[0];if(!['Deployment','StatefulSet','DaemonSet'].includes(parsed?.kind)||!parsed.spec?.template?.spec?.containers||!parsed.metadata)throw Error('需要包含 metadata 和 Pod 模板的 apps/v1 工作负载');if(typeof parsed.metadata!=='object'||Array.isArray(parsed.metadata)||!Array.isArray(parsed.spec.template.spec.containers)||parsed.spec.template.spec.containers.some(c=>!c||typeof c!=='object'||Array.isArray(c)))throw Error('metadata 必须为对象，containers 必须是容器对象数组');for(const key of ['initContainers','volumes','imagePullSecrets','tolerations']){const value=parsed.spec.template.spec[key];if(value!==undefined&&(!Array.isArray(value)||value.some(item=>!item||typeof item!=='object'||Array.isArray(item))))throw Error(key+' 必须为对象数组')}if(parsed.spec.volumeClaimTemplates!==undefined&&!Array.isArray(parsed.spec.volumeClaimTemplates))throw Error('volumeClaimTemplates 必须为数组');parsed.spec.template.metadata||={};if(parsed.metadata.namespace&&parsed.metadata.namespace!==namespace)throw Error('YAML 命名空间与当前范围不一致');if(editing&&(parsed.metadata.name!==route.params.name||parsed.kind.toLowerCase()!==route.params.kind))throw Error('编辑不能更改资源类型和名称');parsed.metadata.namespace=namespace;object.value=parsed;group.value='containers';selected.value=0;error.value='';return true}catch(e){error.value=e.message;return false}}
function normalize(){const key=object.value.kind==='Deployment'?'strategy':'updateStrategy';if(object.value.spec[key]?.type!=='RollingUpdate'&&object.value.spec[key])delete object.value.spec[key].rollingUpdate}
function switchMode(value){if(loadFailed.value||value===mode.value)return;if(Object.keys(fieldErrors).length){error.value=Object.values(fieldErrors).join('；');return;}if(value==='form'&&!parseYaml())return;if(value==='yaml'){normalize();yamlText.value=dump(object.value,{lineWidth:-1,noRefs:true})}mode.value=value;errors.value=[]}
function validateYaml(){if(parseYaml()){errors.value=validate(object.value);if(!errors.value.length)ElMessage.success('本地字段校验通过，提交时仍需服务端验证')}}
function simplifyYaml(){if(!parseYaml())return;if(editing){copyYaml(dump(simplify(object.value),{lineWidth:-1,noRefs:true}));return}yamlText.value=dump(simplify(object.value),{lineWidth:-1,noRefs:true});ElMessage.success('已清理状态与服务端字段，用户配置保留')}
function reviewYaml(){if(parseYaml()){mode.value='form';step.value=4;errors.value=validate(object.value)}}
async function importFile(event){const file=event.target.files?.[0];if(file)yamlText.value=await file.text()}
async function copyYaml(value){try{await copyText(value);ElMessage.success('已复制 YAML')}catch{ElMessage.warning('当前浏览器不允许剪贴板访问，请手动复制')}}
async function submit(){if(loadFailed.value||saving.value)return;if(Object.keys(fieldErrors).length){error.value=Object.values(fieldErrors).join('；');return}if(editing&&(object.value.metadata.name!==route.params.name||object.value.kind.toLowerCase()!==route.params.kind)){error.value='编辑不能更改资源类型和名称';return}normalize();errors.value=validate(object.value);if(errors.value.length)return;const payload=editing?object.value:simplify(object.value);saving.value=true;try{await http({method:editing?'put':'post',url:'/resources',data:{kind:payload.kind.toLowerCase(),yaml:dump(payload,{noRefs:true})}});ElMessage.success(editing?'配置已保存':'资源已创建');router.push('/workloads/'+payload.kind.toLowerCase()+'/'+encodeURIComponent(namespace)+'/'+encodeURIComponent(payload.metadata.name))}catch(e){error.value=e.response?.data?.error||e.message}finally{saving.value=false}}
onMounted(async()=>{if(!editing&&window.history.state.workloadDraft){yamlText.value=window.history.state.workloadDraft;parseYaml()}if(editing){loading.value=true;try{const raw=await http.get('/resource',{params:{kind:route.params.kind,namespace,name:route.params.name},responseType:'text'});yamlText.value=raw;loadFailed.value=!parseYaml()}catch(e){loadFailed.value=true;error.value='配置加载失败，已禁止保存：'+(e.response?.data?.error||e.message)}finally{loading.value=false}}if(mode.value==='yaml')yamlText.value=dump(object.value,{lineWidth:-1,noRefs:true})})
</script>
<style scoped>
.editor-title{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:24px}.editor-title h1{font-size:25px;margin:12px 0}.muted{font-size:12px;color:var(--ks-text-secondary);line-height:1.7}.editor-steps{margin-bottom:24px}.editor-steps :deep(.el-step){cursor:pointer}.editor-layout{display:grid;grid-template-columns:minmax(0,1fr) 190px;gap:20px}.editor-content{min-width:0}.editor-summary{align-self:start}.editor-summary dt{color:var(--ks-text-secondary);font-size:12px;margin-top:18px}.editor-summary dd{margin:6px 0;overflow-wrap:anywhere}.editor-toolbar,.container-choices{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:20px}.editor-toolbar h2{margin-right:auto}.editor-toolbar .el-select{width:220px}.section-gap{margin-top:24px}h2{font-size:16px;margin:0 0 20px}.editor-footer{display:flex;justify-content:space-between;align-items:center;padding:20px;background:white;border:1px solid var(--ks-border);border-radius:6px}.yaml-input :deep(textarea){font-family:monospace;line-height:1.7}.editor-preview{background:#202b3b;color:#dce9e4;padding:20px;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:6px}.review-summary{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:24px}.review-summary span,.review-summary strong{display:block}.review-summary span{color:var(--ks-text-secondary);font-size:12px;margin-bottom:6px}.validation-errors{padding:16px;color:var(--ks-danger);background:#fff2f2;border-radius:6px;margin-bottom:20px;overflow-wrap:anywhere;font-size:12px}@media(max-width:1000px){.editor-layout{grid-template-columns:1fr}.editor-summary{display:none}}
</style>
